From c5de7bb19789badedca127b24a53b4b5eb221321 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 16:57:29 +0100
Subject: [PATCH] kded: leave virtual devices alone when muting globally

The speaker and microphone mute shortcuts muted every device, including
virtual ones used for effects and routing, silencing recordings and
streams. Now virtual devices are only muted when they are the default.

BUG: 508170
---
 src/kded/audioshortcutsservice.cpp | 16 ++++++++++++++--
 1 file changed, 14 insertions(+), 2 deletions(-)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..6e588c9b 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -30,6 +30,12 @@ K_PLUGIN_CLASS_WITH_JSON(AudioShortcutsService, "audioshortcutsservice.json")
 constexpr QLatin1String OSD_DBUS_SERVICE = "org.kde.plasmashell"_L1;
 constexpr QLatin1String OSD_DBUS_PATH = "/org/kde/osdService"_L1;

+// Virtual devices (effects, routing) feed a physical device, muting them would also silence recordings
+static bool isGlobalMuteTarget(const PulseAudioQt::AbstractModel *model, const QModelIndex &index)
+{
+    return !model->data(index, model->role("VirtualDevice"_ba)).toBool() || model->data(index, model->role("Default"_ba)).toBool();
+}
+
 AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVariant> &)
     : KDEDModule(parent)
     , m_sinkModel(new PulseAudioQt::SinkModel(this))
@@ -404,6 +410,9 @@ void AudioShortcutsService::applyGlobalSinkMute(const QModelIndex &index, const
     const QString deviceId = name % "." % activePortIdx;

     if (globalMute) {
+        if (!isGlobalMuteTarget(m_sinkModel, index)) {
+            return;
+        }
         // Mute the device if unmuted
         const bool isUnmuted = !m_sinkModel->data(index, m_sinkModel->role("Muted"_ba)).toBool();
         if (isUnmuted) {
@@ -427,6 +436,9 @@ void AudioShortcutsService::applyGlobalSourceMute(const QModelIndex &index, cons
     const QString deviceId = name % "." % activePortIdx;

     if (globalMute) {
+        if (!isGlobalMuteTarget(m_sourceModel, index)) {
+            return;
+        }
         // Mute the device if unmuted
         const bool isUnmuted = !m_sourceModel->data(index, m_sourceModel->role("Muted"_ba)).toBool();
         if (isUnmuted) {
@@ -492,7 +504,7 @@ void AudioShortcutsService::handleSinkDataChanged(const QModelIndex &topLeft, co

             m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
             m_globalConfig->save();
-        } else if (globalMute && (volumeChanged || (mutedChanged && isUnmuted))) {
+        } else if (globalMute && (volumeChanged || (mutedChanged && isUnmuted)) && isGlobalMuteTarget(m_sinkModel, index)) {
             // Changes to volume or unmuting break global mute
             disableGlobalSinkMute();
         }
@@ -518,7 +530,7 @@ void AudioShortcutsService::handleSourceDataChanged(const QModelIndex &topLeft,

             m_globalConfig->setGlobalMuteSourcesMutedDevices(globalMicMuteMutedDevices);
             m_globalConfig->save();
-        } else if (globalMicMute && (volumeChanged || (mutedChanged && isUnmuted))) {
+        } else if (globalMicMute && (volumeChanged || (mutedChanged && isUnmuted)) && isGlobalMuteTarget(m_sourceModel, index)) {
             // Changes to volume or unmuting break global mute
             disableGlobalSourceMute();
         }
